(function(global,factory){typeof module==="object"&&module.exports?module.exports=factory():global.HKIDOCR=factory()})(this,function(){return class{constructor(){this.tesseract=window.Tesseract}async recognize(imageFile){try{const{data:{text}}=await this.tesseract.recognize(imageFile,"eng+chi_tra",{logger:()=>{},tessedit_pageseg_mode:6});const info=this._extractInfo(text);return{success:true,name:info.name,idNumber:info.idNumber,dateOfBirth:info.dateOfBirth,rawText:text}}catch(err){return{success:false,error:err.message}}}_extractInfo(text){const lines=text.split("\n").map(l=>l.trim()).filter(Boolean);let name=null;let idNumber=null;let dateOfBirth=null;const idMatch=text.match(/[A-Z]{1,2}\d{6}[\(]?[0-9A-Z]/i);if(idMatch){idNumber=idMatch[0].replace(/[()]/g,"").toUpperCase()}const dateMatch=text.match(/\d{2}[-/]\d{2}[-/]\d{4}/);if(dateMatch){dateOfBirth=dateMatch[0]}name=this._findName(lines,text);return{name,idNumber,dateOfBirth}}_findName(lines,fullText){const blacklist=["HONG KONG","IDENTITY","BIRTH","DATE","ISSUE","簽發","性別","出生日期"];const nameMatch=fullText.match(/[A-Z]{2,},\s*[A-Z][a-z]+/i);if(nameMatch){const candidate=nameMatch[0].replace(/[^A-Za-z,\s]/g,"").trim();if(candidate&&!blacklist.some(b=>candidate.includes(b))){return candidate.replace(","," ").trim()}}for(const line of lines){const t=line.trim();if(blacklist.some(b=>t.includes(b)))continue;if(t.includes(",")){const clean=t.replace(/[^A-Za-z,\s]/g,"").trim();if(clean&&clean.length>3){return clean.replace(","," ").trim()}}const words=t.split(/\s+/).filter(w=>w.length>0);if(words.length>=2&&words.length<=4){const allAlpha=words.every(w=>/[A-Za-z]/.test(w));if(allAlpha){return t.replace(/[^A-Za-z\s]/g,"").trim()}}}return null}}});
